def middle_characters(s):
    if not s:
        return ""
    mid = len(s) // 2
    if len(s) % 2 == 1:
        return s[mid]
    return s[mid-1:mid+1]

def can_become_palindrome_by_removing_one(s):
    def is_pal(sub):
        return sub == sub[::-1]
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return is_pal(s[l+1:r+1]) or is_pal(s[l:r])
        l += 1
        r -= 1
    return True

def count_leading_zeros(s):
    count = 0
    for ch in s:
        if ch == '0':
            count += 1
        else:
            break
    return count

def longest_consecutive_alphabetical_run(s):
    if not s:
        return ""
    best = ""
    cur = s[0]
    for i in range(1, len(s)):
        prev_ch, ch = s[i-1], s[i]
        if prev_ch.isalpha() and ch.isalpha() and ord(ch.lower()) - ord(prev_ch.lower()) == 1:
            cur += ch
        else:
            cur = ch
        if len(cur) > len(best):
            best = cur
    return best

def count_word_length_frequency(s):
    freq = {}
    for w in s.split():
        freq[len(w)] = freq.get(len(w), 0) + 1
    return freq

def has_repeated_substring_pattern(s):
    if not s:
        return False
    return s in (s + s)[1:-1]

def shift_letters_by_position(s):
    out = []
    for i, ch in enumerate(s):
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + i) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def replace_digits_with_words(s):
    names = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(names[int(ch)])
        else:
            out.append(ch)
    return ''.join(out)

def find_longest_palindrome_word(s):
    best = ""
    for w in s.split():
        lw = w.lower()
        if lw == lw[::-1] and len(w) > len(best):
            best = w
    return best

def count_char_type_groups(s):
    if not s:
        return 0
    def kind(ch):
        if ch.isalpha():
            return 'alpha'
        if ch.isdigit():
            return 'digit'
        return 'other'
    groups = 1
    for i in range(1, len(s)):
        if kind(s[i]) != kind(s[i-1]):
            groups += 1
    return groups

def mask_string(s, visible):
    if len(s) <= 2 * visible:
        return s
    return s[:visible] + '*' * (len(s) - 2 * visible) + s[len(s)-visible:]

def count_vowel_runs(s):
    runs = 0
    in_run = False
    for ch in s:
        if ch.lower() in "aeiou":
            if not in_run:
                runs += 1
                in_run = True
        else:
            in_run = False
    return runs

def remove_nth_word(s, n):
    words = s.split()
    if 0 <= n < len(words):
        del words[n]
    return ' '.join(words)

def swap_first_last_char(s):
    if len(s) < 2:
        return s
    return s[-1] + s[1:-1] + s[0]
